const lesNum = id => ROAD[id] ? ROAD[id].n : "";
function lesPre(id) {
  const R = ROAD[id]; if (!R || !R.pre.length) return "";
  return `<p class="lespre"><span>Prima devi sapere</span>${R.pre.filter(p => LESSONS[p]).map(p => `<button type="button" data-lespre="${p}">${lesNum(p)} ${LESSONS[p].t.replace(/:.*$/, "")}</button>`).join("")}</p>`;
}
/* sottolinea, solo nel testo e una volta per termine, i termini usati prima della lezione che li spiega */
function lesGloss(id, html) {
  const me = ROAD[id] ? ROAD[id].o : 1e9, done = new Set();
  const W = "A-Za-z0-9àèéìòùÀÈÉÌÒÙ";
  const items = GLOSS.map((g, i) => [g, i]).filter(([g]) => ROAD[g[2]] && ROAD[g[2]].o > me);
  if (!items.length) return html;
  return html.split(/(<style[\s\S]*?<\/style>|<p class="lx-tf-e" hidden>[\s\S]*?<\/p>|<[^>]+>)/).map(seg => {
    if (!seg || seg[0] === "<") return seg;
    items.forEach(([g, i]) => {
      if (done.has(i)) return;
      for (const t of g[0]) {
        const re = new RegExp(`(^|[^${W}/-])(${t.replace(/[.*+?^${}()|[\]\\/]/g, "\\$&")})(?![${W}-])`, t === "EV" || t === "GTO" || t === "SPR" || t === "HUD" || t === "MDF" || t === "PFR" || t === "VPIP" ? "" : "i");
        if (re.test(seg)) { seg = seg.replace(re, (m, a, b) => `${a}<span class="lx-gl" role="button" tabindex="0" data-gl="${i}">${b}</span>`); done.add(i); break; }
      }
    });
    return seg;
  }).join("");
}
document.addEventListener("click", e => {
  /* i termini del glossario ([data-gl]) aprono il fumetto della spiegazione: js/app/72-termini.js */
  const p = e.target.closest("[data-lespre]");
  if (p) { const L = LESSONS[p.dataset.lespre]; e.preventDefault(); e.stopPropagation(); return gModal(`<div class="lesbody"><span class="eyebrow">Ripasso · lezione ${lesNum(L.id)}</span><h3 style="margin:4px 0 8px">${L.t}</h3>${lesGloss(L.id, L.card)}</div>`); }
}, true);
document.addEventListener("keydown", e => { if ((e.key === "Enter" || e.key === " ") && e.target.closest && e.target.closest("[data-gl]")) { e.preventDefault(); e.target.click(); } });

